cd /tmp/vally-eval-trial-4zEiwE && mkdir -p tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount .copilot-tracking/skraft-plans/pricing/features && cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Returning_customer_in_Bronze_tier_is_charged_9500_cents_for_a_10000_cent_basket()
    {
        // Returning customer in the Bronze tier is charged the Bronze price
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -25

